/**
 * RevPack target (finished part) models: each public pack's target is a real
 * solid of what that pack's program cuts, as STEP (read through OpenCascade,
 * the extension's STEP path) and STL (the shared kernel's reader, which CAM
 * and the hub use). Generated by scripts/revpack-targets/generate_targets.py.
 *
 * Also pins the seeded-error pack: every finding is a real mistake in
 * O05002.nc, and the clean O05001.nc has none and uses only G54.
 *
 * Run via: npm run test:revpack
 */
import { describe, it } from 'node:test';
import * as assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { isSeededTestPack, targetStlFile, type RevPack } from '../src/providers/visualizer/revpack';
import { correlateProgramWithRevPack } from '../src/providers/visualizer/revpackCorrelation';
import { buildRevPackGeometry, loadStl, meshVolume, type GeoMesh } from '../src/providers/visualizer/revpackGeometry';
import { tessellateSTEP } from '../src/providers/visualizer/stepTessellator';
import { readRevPack, revPackStepTargetMessage, revPackTargetMessage } from '../src/providers/visualizer/revpackLoader';

const root = path.join(__dirname, 'fixtures', 'revpack-public');
const load = (dir: string) => {
  const pack = JSON.parse(fs.readFileSync(path.join(root, dir, 'revpack.json'), 'utf8')) as RevPack;
  return { pack, gcode: fs.readFileSync(path.join(root, dir, pack.program.file), 'utf8') };
};
const stlOf = (dir: string, pack: RevPack): GeoMesh => loadStl(fs.readFileSync(path.join(root, dir, targetStlFile(pack)!)));

/** Ray cast along +Z: is the point inside the closed triangle soup? */
function inside(mesh: GeoMesh, x0: number, y0: number, z: number): boolean {
  // Nudge off the exact grid so the ray never runs down a shared triangle edge.
  const x = x0 + 1.234e-5, y = y0 + 2.345e-5;
  const p = mesh.positions;
  let hits = 0;
  for (let o = 0; o + 8 < p.length; o += 9) {
    const ax = p[o], ay = p[o + 1], bx = p[o + 3], by = p[o + 4], cx = p[o + 6], cy = p[o + 7];
    const det = (by - cy) * (ax - cx) + (cx - bx) * (ay - cy);
    if (Math.abs(det) < 1e-14) continue;
    const l1 = ((by - cy) * (x - cx) + (cx - bx) * (y - cy)) / det;
    const l2 = ((cy - ay) * (x - cx) + (ax - cx) * (y - cy)) / det;
    const l3 = 1 - l1 - l2;
    if (l1 < 0 || l2 < 0 || l3 < 0) continue;
    if (l1 * p[o + 2] + l2 * p[o + 5] + l3 * p[o + 8] > z) hits++;
  }
  return hits % 2 === 1;
}

const PACKS = ['haas-umc750-5axis', 'haas-vf2-vise', 'okuma-lb3000-lathe', 'trumpf-trulaser3030'];

describe('RevPack targets: STEP + STL of the same solid', () => {
  for (const dir of PACKS) {
    it(`${dir}: STEP (OpenCascade, pack units) and STL agree and sit inside the stock`, async () => {
      const { pack } = load(dir);
      assert.equal(pack.target?.format, 'step');
      assert.ok(pack.target?.stl, 'an STL travels with the STEP for hosts without OpenCascade');
      const stl = stlOf(dir, pack);
      assert.ok(stl.triangleCount > 60, `${dir} target is a real part, not a placeholder primitive (${stl.triangleCount} triangles)`);
      const step = await tessellateSTEP(new Uint8Array(fs.readFileSync(path.join(root, dir, pack.target!.file))), { linearUnit: pack.units === 'in' ? 'inch' : 'millimeter' });
      const tol = pack.units === 'in' ? 0.002 : 0.05;
      const sb = [step.bounds.minX, step.bounds.minY, step.bounds.minZ, step.bounds.maxX, step.bounds.maxY, step.bounds.maxZ];
      const lb = [...stl.bounds.min, ...stl.bounds.max];
      sb.forEach((v, k) => assert.ok(Math.abs(v - lb[k]) <= tol, `bound ${k}: STEP ${v} vs STL ${lb[k]} (units ${pack.units})`));
      const stock = pack.stock as { min?: number[]; max?: number[]; diameter?: number; zMin?: number; zMax?: number };
      if (stock.min && stock.max) {
        for (let k = 0; k < 3; k++) {
          assert.ok(lb[k] >= stock.min[k] - tol && lb[k + 3] <= stock.max[k] + tol, `target inside stock on axis ${k}`);
        }
      } else {
        assert.ok(Math.max(Math.abs(lb[0]), Math.abs(lb[3])) <= stock.diameter! / 2 + tol);
        assert.ok(lb[2] >= stock.zMin! - tol && lb[5] <= stock.zMax! + tol);
      }
    });
  }

  it('the loader sends the STL at once and the STEP through OpenCascade, cross-checked', async () => {
    const loaded = readRevPack(path.join(root, 'haas-umc750-5axis', 'revpack.json'));
    const stl = revPackTargetMessage(loaded)!;
    assert.equal(stl.loader, 'stl');
    assert.equal(stl.displayMode, 'solid');
    const step = (await revPackStepTargetMessage(loaded))!;
    assert.equal(step.loader, 'step-occt');
    assert.equal(step.id, stl.id, 'the STEP replaces the STL target in place');
    assert.ok(step.stlCrossCheck?.ok, JSON.stringify(step.stlCrossCheck));
  });
});

describe('RevPack targets match what each program cuts', () => {
  it('UMC-750 bracket: faced top, R0.25 pocket, two side holes from the B90 drill, 45 deg chamfers', () => {
    const { pack, gcode } = load('haas-umc750-5axis');
    const t = stlOf('haas-umc750-5axis', pack);
    assert.ok(Math.abs(t.bounds.max[2] - -0.05) < 1e-4, 'face at Z-0.05 (T1 lines 15-24)');
    assert.ok(!inside(t, 0, 0, -0.2), 'pocket floor at Z-0.3');
    assert.ok(inside(t, 0, 0, -0.35), 'material under the pocket');
    assert.ok(!inside(t, 0.45, 0.0, -0.2) && inside(t, 0.55, 0.0, -0.2), 'pocket wall at X0.5 (0.25 path + 0.25 radius)');
    const report = correlateProgramWithRevPack(gcode, pack);
    const drills = report.segments.filter(s => s.tool === 3 && !s.rapid);
    assert.equal(drills.length, 2, 'two G83 holes');
    for (const seg of drills) {
      assert.ok(!inside(t, -1.3, seg.to[1], seg.to[2]), `hole at part Y${seg.to[1]} Z${seg.to[2]}`);
      assert.ok(inside(t, -1.3, seg.to[1] + 0.15, seg.to[2]), 'solid beside the hole');
    }
    assert.ok(!inside(t, 0, -0.96, -0.08), 'chamfer removed the -Y top edge');
    assert.ok(!inside(t, 1.46, 0, -0.08), 'chamfer removed the +X top edge');
    assert.ok(inside(t, 0, -0.9, -0.3) && inside(t, -1.46, 0.5, -0.3), 'untouched edges stay');
  });

  it('UMC-750 and VF-2: from above, the in-process stock is on size against the target (no remaining, no gouge)', () => {
    for (const dir of ['haas-umc750-5axis', 'haas-vf2-vise']) {
      const { pack, gcode } = load(dir);
      const report = correlateProgramWithRevPack(gcode, pack);
      const g = buildRevPackGeometry(pack, { segments: report.segments, targetStl: fs.readFileSync(path.join(root, dir, targetStlFile(pack)!)) });
      const cmp = g.inProcess!.comparison!;
      assert.equal(cmp.gouge, 0, `${dir} gouge cells`);
      assert.equal(cmp.remaining, 0, `${dir} remaining cells`);
    }
  });

  it('VF-2 plate: faced to Z-0.02 with four through holes at the drilled positions', () => {
    const { pack } = load('haas-vf2-vise');
    const t = stlOf('haas-vf2-vise', pack);
    assert.ok(Math.abs(t.bounds.max[2] - -0.02) < 1e-4);
    for (const [x, y] of [[-1.25, -0.75], [1.25, -0.75], [1.25, 0.75], [-1.25, 0.75]]) {
      assert.ok(!inside(t, x, y, -0.4), `hole at ${x},${y}`);
      assert.ok(inside(t, x + 0.2, y, -0.4));
    }
  });

  it('LB3000 shaft: diameters, chamfer and both 3 mm grooves follow the finish and groove passes', () => {
    const { pack, gcode } = load('okuma-lb3000-lathe');
    const t = stlOf('okuma-lb3000-lathe', pack);
    const report = correlateProgramWithRevPack(gcode, pack);
    const width = (tool: number | null) => pack.tools.find(x => x.t === tool && /groov/i.test(x.type))?.diameter ?? 0;
    // Program radius at z: smallest radius any feed move reaches there (a
    // grooving insert covers its width toward -Z from its reference corner).
    const cutRadius = (z: number) => {
      let r = 40;
      for (const s of report.segments) {
        if (s.rapid) continue;
        const w = width(s.tool);
        const [z0, z1] = [Math.min(s.from[2], s.to[2]) - w, Math.max(s.from[2], s.to[2])];
        if (z < z0 - 1e-9 || z > z1 + 1e-9) continue;
        const f = s.to[2] === s.from[2] ? 1 : (z - s.from[2]) / (s.to[2] - s.from[2]);
        const rad = w ? Math.min(s.from[0], s.to[0]) : s.from[0] + (s.to[0] - s.from[0]) * Math.max(0, Math.min(1, f));
        r = Math.min(r, rad);
      }
      return r;
    };
    const targetRadius = (z: number) => {
      for (let r = 40.5; r > 0; r -= 0.05) if (inside(t, r, 0.001, z)) return r;
      return 0;
    };
    for (const z of [-1, -6, -13.5, -20, -35, -43.5, -50, -90]) {
      assert.ok(Math.abs(targetRadius(z) - cutRadius(z)) < 0.1, `z ${z}: target r ${targetRadius(z).toFixed(2)} vs program r ${cutRadius(z).toFixed(2)}`);
    }
  });

  it('TruLaser nest: six 200 x 150 parts in 3 mm sheet, cut on the line (0.2 kerf)', () => {
    const { pack } = load('trumpf-trulaser3030');
    const t = stlOf('trumpf-trulaser3030', pack);
    assert.ok(Math.abs(meshVolume(t.positions) - 6 * 199.8 * 149.8 * 3) < 1);
    for (const [x, y] of [[150, 125], [400, 125], [650, 125], [150, 375], [400, 375], [650, 375]]) assert.ok(inside(t, x, y, -1.5), `part at ${x},${y}`);
    assert.ok(!inside(t, 275, 125, -1.5), 'skeleton between parts is not part of the target');
  });
});

describe('Seeded test pack (UMC-750, O05002.nc)', () => {
  it('is marked as a seeded test pack and named so', () => {
    const { pack } = load('haas-umc750-5axis-seeded');
    assert.ok(isSeededTestPack(pack));
    assert.match(pack.name, /seeded test pack/i);
    assert.match(pack.name, /intentional/i);
  });

  it('the clean O05001 has no findings and uses only G54, which its pack defines', () => {
    const { pack, gcode } = load('haas-umc750-5axis');
    const report = correlateProgramWithRevPack(gcode, pack);
    assert.deepEqual(report.findings, []);
    assert.deepEqual(report.workOffsetsUsed, ['G54']);
    assert.deepEqual(Object.keys(pack.workOffsets), ['G54']);
  });

  it('every seeded finding is a real mistake on the program line that makes it', () => {
    const { pack, gcode } = load('haas-umc750-5axis-seeded');
    const lines = gcode.split(/\r?\n/);
    const report = correlateProgramWithRevPack(gcode, pack);
    // id -> [line, text on that line that is the mistake]
    const expected: Array<[string, number, RegExp]> = [
      ['undefined-work-offset-G55', 7, /G55/],              // pack defines only G54
      ['rapid-into-stock', 14, /^X0\. Y0\./],               // G00 at Z-0.5 across uncut stock
      ['unsafe-tool-change', 16, /T2 M06/],                 // no G28 Z0 before the change
      ['tool-length-mismatch-T2', 18, /G43 H01/],           // T2 with T1's length
      ['simultaneous-5x-without-tcpc', 20, /X1\.5 B10\./],  // B and X together, no G234
      ['tool-not-in-revpack-T4', 24, /T4 M06/],
      ['over-travel-B', 25, /B-40\./],                      // UMC-750 B is -35..+120
      ['rpm-over-machine', 26, /S9000/],                    // UMC-750 spindle 8100 rpm
      ['rapid-into-jaw', 30, /G00 Z-1\.6/],                 // beside the part, rapid down into the Makro-Grip +Y jaw
    ];
    const errors = report.findings.filter(f => f.severity === 'error');
    assert.deepEqual(errors.map(f => `${f.line}:${f.id}`), expected.map(([id, line]) => `${line}:${id}`));
    for (const [id, line, re] of expected) assert.match(lines[line - 1], re, `${id} points at "${lines[line - 1]}"`);
    // The retract out of the line-14 crash is the same crash, not a new one.
    assert.ok(!report.findings.some(f => f.line === 15), 'no cascade finding on the retract (line 15)');
  });
});
